58	// Enqueue appends a ref to the queue. It is safe to enqueue a ref already
59	// present (or already pushed): Drain collapses duplicates and the batch push is
60	// idempotent. Enqueue takes the lock so concurrent writers never interleave a
61	// partial line.
62	func (q *PushQueue) Enqueue(ref plumbing.ReferenceName) error {
63		release, err := flock.Acquire(q.lockPath())
64		if err != nil {
65			return fmt.Errorf("lock push queue: %w", err)
66		}
67		defer release()
68	
69		line, err := json.Marshal(pushQueueEntry{Ref: ref.String()})
70		if err != nil {
71			return fmt.Errorf("encode push queue entry: %w", err)
72		}
73		f, err := os.OpenFile(q.queuePath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
74		if err != nil {
75			return fmt.Errorf("open push queue: %w", err)
76		}
77		defer f.Close()
78		if _, err := f.Write(append(line, '\n')); err != nil {
79			return fmt.Errorf("append push queue entry: %w", err)
80		}
81		return nil
82	}
