144	// rewriteLocked replaces the queue file with exactly refs (de-duplicated, one
145	// line each), or removes the file when refs is empty so a clean repo has no
146	// stray queue. The caller must hold the lock. The write is atomic (temp file +
147	// rename) so a concurrent reader never sees a half-written queue.
148	func (q *PushQueue) rewriteLocked(refs []plumbing.ReferenceName) error {
149		if len(refs) == 0 {
150			if err := os.Remove(q.queuePath()); err != nil && !os.IsNotExist(err) {
151				return fmt.Errorf("remove empty push queue: %w", err)
152			}
153			return nil
154		}
155		var buf bytes.Buffer
156		for _, r := range refs {
157			line, err := json.Marshal(pushQueueEntry{Ref: r.String()})
158			if err != nil {
159				return fmt.Errorf("encode push queue entry: %w", err)
160			}
161			buf.Write(line)
162			buf.WriteByte('\n')
163		}
164		if err := writeFileAtomicInDir(q.dir, q.queuePath(), buf.Bytes()); err != nil {
165			return fmt.Errorf("rewrite push queue: %w", err)
166		}
167		return nil
168	}
