170	// readLocked parses the queue file into de-duplicated refs, preserving first-seen
171	// order. The caller must hold the lock. Malformed lines are skipped rather than
172	// failing the whole drain — a single bad record must not strand every queued ref.
173	//
174	// rawLines is the number of non-empty lines seen (including duplicates and
175	// malformed records), so callers can detect when the file holds more than the
176	// de-duplicated set and is worth compacting: rawLines > len(refs) exactly when
177	// there were redundant lines.
178	func (q *PushQueue) readLocked() (refs []plumbing.ReferenceName, rawLines int, err error) {
179		f, err := os.Open(q.queuePath())
180		if err != nil {
181			if os.IsNotExist(err) {
182				return nil, 0, nil
183			}
184			return nil, 0, fmt.Errorf("open push queue: %w", err)
185		}
186		defer f.Close()
187	
188		seen := make(map[string]struct{})
189		scanner := bufio.NewScanner(f)
190		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
191		for scanner.Scan() {
192			line := bytes.TrimSpace(scanner.Bytes())
193			if len(line) == 0 {
194				continue
195			}
196			rawLines++
197			var entry pushQueueEntry
198			if err := json.Unmarshal(line, &entry); err != nil || entry.Ref == "" {
199				continue
200			}
201			if _, dup := seen[entry.Ref]; dup {
202				continue
203			}
204			seen[entry.Ref] = struct{}{}
205			refs = append(refs, plumbing.ReferenceName(entry.Ref))
206		}
207		if err := scanner.Err(); err != nil {
208			return nil, 0, fmt.Errorf("read push queue: %w", err)
209		}
210		return refs, rawLines, nil
211	}
