213	// writeFileAtomicInDir writes data to a temp file in dir and renames it over
214	// path, so a reader (under the lock) never sees a half-written queue.
215	func writeFileAtomicInDir(dir, path string, data []byte) error {
216		tmp, err := os.CreateTemp(dir, pushQueueFileName+".*")
217		if err != nil {
218			return fmt.Errorf("create temp push queue: %w", err)
219		}
220		tmpName := tmp.Name()
221		defer os.Remove(tmpName)
222		if _, err := tmp.Write(data); err != nil {
223			_ = tmp.Close()
224			return fmt.Errorf("write temp push queue: %w", err)
225		}
226		if err := tmp.Close(); err != nil {
227			return fmt.Errorf("close temp push queue: %w", err)
228		}
229		if err := os.Rename(tmpName, path); err != nil {
230			return fmt.Errorf("rename temp push queue: %w", err)
231		}
232		return nil
233	}
